const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=defaultState();let state=initial;try{const saved=JSON.parse(localStorage.getItem('iron-room-v1'));if(saved)state=validateProject(saved);}catch{}
let groovePage=0,grooveStyle='All',grooveMeter='All',grooveFeel='All',grooveTempo='All',grooveSort='collection',savedOnly=false,libraryPreview=null,previewRequest=0;
let favorites=new Set();try{favorites=new Set(JSON.parse(localStorage.getItem('iron-room-groove-favorites')||'[]'));}catch{}
let selected='snare',activeTab='kit',grooveFilter='All',search='',selectedNote=null,drawVelocity=100,playing=false,loop=true,nextTime=0,step=0,timer=null,animation=null,uiQueue=[],lastUi=-1,history=[],future=[],saveTimer,previewName=null,midiAccess=null,learn=false,record=false,hatCC=127,dragData=null,toastTimer,initInProgress=false;
const engine=new DrumEngine(state,(n,total)=>{$('#sampleStatus').innerHTML=`<i></i> LOADING ${Math.round(n/total*100)}%`;$('#playBtn').textContent=`${Math.round(n/total*100)}%`;});
const pattern=()=>state.patterns[state.active];
function validateProject(s){if(s.version!==1||!Array.isArray(s.patterns)||!s.patterns.length||s.patterns.length>200||!Array.isArray(s.channels)||!s.master)throw Error('This is not an Iron Room project.');const d=defaultState();const number=(x,a,b,f)=>Number.isFinite(+x)?Math.max(a,Math.min(b,+x)):f;d.title=String(s.title||'Untitled session').slice(0,80);d.bpm=number(s.bpm,30,300,112);d.swing=number(s.swing,0,65,0);d.humanize=number(s.humanize,0,30,8);d.velocityHumanize=number(s.velocityHumanize,0,20,5);d.mode=s.mode==='song'?'song':'pattern';d.patterns=s.patterns.map(p=>{if(!SIGNATURES[p.signature]||!Array.isArray(p.events))throw Error('Invalid pattern data');const bars=Math.round(number(p.bars,1,64,2));return {id:String(p.id||crypto.randomUUID()),libraryId:typeof p.libraryId==='string'?p.libraryId:undefined,loop:p.loop?loopBounds({...p,bars},SIGNATURES[p.signature]):undefined,feel:['Straight','Shuffle','Swing','Triplet'].includes(p.feel)?p.feel:undefined,name:String(p.name||'Untitled').slice(0,80),bars,signature:p.signature,events:p.events.slice(0,30000).filter(e=>LANES.some(l=>l.id===e.lane)&&Number.isFinite(e.step)&&e.step>=0&&e.step<bars*SIGNATURES[p.signature]&&e.step+(e.offset||0)>=0&&e.step+(e.offset||0)<bars*SIGNATURES[p.signature]).map(e=>({lane:e.lane,step:Math.round(e.step),velocity:Math.round(number(e.velocity,1,127,100)),prob:number(e.prob,0,1,1),offset:number(e.offset,-.5,.999999,0)}))};});d.active=Math.round(number(s.active,0,d.patterns.length-1,0));d.song=Array.isArray(s.song)?s.song.slice(0,64).filter(c=>Number.isInteger(c.pattern)&&d.patterns[c.pattern]).map(c=>({pattern:c.pattern,repeats:Math.round(number(c.repeats,1,16,1))})):[];for(const c of d.channels){const saved=s.channels.find(x=>x.id===c.id);if(!saved)continue;for(const k of ['mute','solo','polarity'])c[k]=!!saved[k];for(const [k,a,b]of [['volume',0,1.5],['pan',-1,1],['tune',-12,12],['decay',.05,1],['low',-12,12],['mid',-12,12],['high',-12,12],['hpf',20,1000],['comp',0,100],['room',0,1]])c[k]=number(saved[k],a,b,c[k]);}for(const [k,a,b]of [['volume',0,1],['low',-12,12],['high',-12,12],['glue',0,100],['parallel',0,1],['room',0,1]])d.master[k]=number(s.master[k],a,b,d.master[k]);d.variants={};for(const l of LANES){d.variants[l.id]=Math.round(number(s.variants?.[l.id],0,l.variants.length-1,0));}d.midiMap={};for(const [n,id]of Object.entries(s.midiMap||initial?.midiMap||{}))if(+n>=0&&+n<=127&&LANES.some(l=>l.id===id))d.midiMap[n]=id;return d;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function save(){clearTimeout(saveTimer);$('#saveStatus').textContent='Saving…';saveTimer=setTimeout(()=>{try{localStorage.setItem('iron-room-v1',JSON.stringify(state));$('#saveStatus').textContent='Saved locally';}catch{$('#saveStatus').textContent='Download project to save';}},300);}
function checkpoint(){history.push(JSON.stringify(state));if(history.length>50)history.shift();future=[];}
function restore(s){stop();state=validateProject(JSON.parse(s));engine.state=state;selectedNote=null;renderAll();engine.update();save();}
function undo(){if(!history.length)return;future.push(JSON.stringify(state));const s=history.pop();restore(s);}
function redo(){if(!future.length)return;history.push(JSON.stringify(state));const s=future.pop();restore(s);}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal();}
$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')&&e.offsetX<0)$('#modal').close();});
function control(label,key,min,max,value,step=1,unit='',scope='piece'){return `<div class="control"><label>${label}<output data-output="${scope}-${key}">${format(value,unit)}</output></label><input aria-label="${esc(label)}" data-control="${key}" data-scope="${scope}" data-unit="${unit}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;}
function format(v,u){if(u==='dB')return `${v>0?'+':''}${(+v).toFixed(1)} dB`;if(u==='%')return Math.round(v*100)+'%';if(u==='pan')return Math.abs(v)<.02?'C':`${Math.round(Math.abs(v)*100)} ${v<0?'L':'R'}`;return `${Number(v).toFixed(u==='st'?1:0)}${u?' '+u:''}`;}
function renderKit(){const defs=`<defs><radialGradient id="head"><stop stop-color="#646e60"/><stop offset=".65" stop-color="#56614f"/><stop offset="1" stop-color="#353e32"/></radialGradient><radialGradient id="bass"><stop stop-color="#374033"/><stop offset=".78" stop-color="#242d25"/><stop offset="1" stop-color="#131a15"/></radialGradient><radialGradient id="metal"><stop stop-color="#e2c78b"/><stop offset=".12" stop-color="#9d7a43"/><stop offset=".2" stop-color="#d9ba7d"/><stop offset=".38" stop-color="#a38950"/><stop offset=".64" stop-color="#bc9f61"/><stop offset="1" stop-color="#6d5835"/></radialGradient><linearGradient id="rim"><stop stop-color="#b5bca6"/><stop offset=".25" stop-color="#3c473b"/><stop offset=".52" stop-color="#79866e"/><stop offset=".75" stop-color="#c0c8ae"/><stop offset="1" stop-color="#485242"/></linearGradient><filter id="shadow" x="-40%" y="-40%" width="180%" height="180%"><feDropShadow dx="2" dy="8" stdDeviation="7" flood-opacity=".65"/></filter><pattern id="rug" width="12" height="12" patternUnits="userSpaceOnUse"><path d="M0 0L12 12M12 0L0 12" stroke="#839173" stroke-width=".3" opacity=".3"/></pattern></defs>`;
const stand=(x,y)=>`<g stroke="#6e7968" stroke-width="2" opacity=".75"><path d="M${x} ${y}l-14 85m14-85l21 82m-21-82l-38 66"/><circle cx="${x}" cy="${y}" r="4" fill="#171f17"/></g>`;
const drum=(id,cx,cy,r,label,key,bass=false)=>`<g class="kit-piece ${selected===id?'selected':''}" data-lane="${id}" role="button" tabindex="0" aria-label="Play ${label} (${key})"><circle cx="${cx}" cy="${cy+5}" r="${r+3}" fill="#1b2019" stroke="#5a4b30" stroke-width="7" filter="url(#shadow)"/><circle cx="${cx}" cy="${cy}" r="${r}" fill="url(#${bass?'bass':'head'})" stroke="url(#rim)" stroke-width="6"/><circle cx="${cx}" cy="${cy}" r="${r-7}" fill="none" stroke="#9ba98a" stroke-opacity=".3"/>${Array.from({length:8},(_,i)=>{let a=i*Math.PI/4,x=cx+Math.cos(a)*(r-1),y=cy+Math.sin(a)*(r-1);return `<circle cx="${x}" cy="${y}" r="2.7" fill="#a4ad98" stroke="#252f24"/>`}).join('')}<circle class="rim-select" cx="${cx}" cy="${cy}" r="${r+7}"/>${bass?`<text x="${cx}" y="${cy-7}" text-anchor="middle" font-family="sans-serif" font-weight="700" font-size="13" fill="#99a58d" letter-spacing="3">IRON</text><text x="${cx}" y="${cy+7}" text-anchor="middle" font-family="sans-serif" font-size="11" fill="#73856b" letter-spacing="3">ROOM</text>`:''}<text class="kit-key" x="${cx}" y="${cy+(bass?29:5)}" text-anchor="middle">${key.toUpperCase()}</text><text class="kit-label" x="${cx}" y="${cy+r+22}" text-anchor="middle">${label}</text></g>`;
const cym=(id,cx,cy,rx,ry,label,key)=>`<g class="kit-piece ${selected===id?'selected':''}" data-lane="${id}" role="button" tabindex="0" aria-label="Play ${label} (${key})"><ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="url(#metal)" stroke="#ae965e" stroke-width="1" filter="url(#shadow)"/>${[.28,.38,.48,.58,.68,.78,.88,.95].map(n=>`<ellipse cx="${cx}" cy="${cy}" rx="${rx*n}" ry="${ry*n}" stroke="#413c22" fill="none" opacity=".35" stroke-width=".6"/>`).join('')}<ellipse cx="${cx}" cy="${cy-1}" rx="${rx*.16}" ry="${ry*.21}" fill="#967842" stroke="#d7bb7e" stroke-width="1"/><circle cx="${cx}" cy="${cy-1}" r="3" fill="#111b15"/><ellipse class="rim-select" cx="${cx}" cy="${cy}" rx="${rx+5}" ry="${ry+5}"/><text class="kit-key" x="${cx+rx*.4}" y="${cy+6}">${key.toUpperCase()}</text><text class="kit-label" x="${cx}" y="${cy+ry+19}" text-anchor="middle">${label}</text></g>`;
$('#drumKit').innerHTML=`<svg viewBox="0 0 690 380" aria-label="Interactive acoustic drum kit">${defs}<ellipse cx="345" cy="220" rx="258" ry="143" fill="#121b16" opacity=".6"/><ellipse cx="345" cy="220" rx="253" ry="139" fill="url(#rug)" stroke="#7e8e701f"/>${stand(172,126)}${stand(507,105)}${stand(577,153)}${stand(112,213)}${stand(440,135)}<g stroke="#56624e" stroke-width="3"><path d="M286 266l-31 67m142-67l30 67m-94-145l-10-63m45 71l24-67"/></g>${drum('kick',346,242,78,'KICK','b',true)}${drum('tomhi',294,147,43,'RACK TOM','r')}${drum('tomlo',460,244,58,'FLOOR TOM','t')}${drum('snare',228,252,53,'SNARE','f')}${cym('crash1',165,112,76,42,'CRASH L','q')}${cym('crash2',500,96,80,44,'CRASH R','w')}${cym('china',585,176,59,34,'CHINA','u')}${cym('ride',447,166,73,42,'RIDE','e')}${cym('splash',370,96,40,24,'SPLASH','i')}${cym('closed',120,229,53,29,'HI-HAT','h')}<g class="kit-piece" data-lane="cowbell" role="button" tabindex="0" aria-label="Play cowbell (o)"><path d="M330 123l-7 29h26l-6-29z" fill="#18231b" stroke="#78876e" stroke-width="2"/><text class="kit-key" x="333" y="146">O</text></g><path d="M329 333l8-24h16l8 24z" fill="#65735c" stroke="#111a13" stroke-width="3"/><path d="M340 316v16m8-16v16" stroke="#a3af95" stroke-width="1"/></svg>`;
}
function renderInspector(){const l=LANES.find(l=>l.id===selected),c=state.channels.find(c=>c.id===l.ch);$('#pieceName').textContent=c.name;$('#pieceArticulation').innerHTML=LANES.filter(x=>x.ch===l.ch).map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(x.name)}</option>`).join('');$('#pieceVariant').innerHTML=l.variants.map((v,i)=>`<option value="${i}">${esc(v.label)}</option>`).join('');$('#pieceVariant').value=state.variants[selected]||0;const groups=engine.variant(l).groups;$('#pieceDescription').textContent=`${groups.length} recorded velocity ${groups.length===1?'layer':'layers'} · up to 3 alternate hits per layer. Stereo overhead recordings.`;
$('#pieceControls').innerHTML=`<div class="control-pair">${control('Tune','tune',-12,12,c.tune,.1,'st')}${control('Decay','decay',.05,1,c.decay,.01,'%')}</div>${control('Level','volume',0,1.5,c.volume,.01,'%')}${control('Pan','pan',-1,1,c.pan,.01,'pan')}${control('Room send','room',0,1,c.room,.01,'%')}<button class="detail-toggle" id="advancedToggle">＋ EQ & dynamics</button><div class="detail-controls" id="advancedControls">${control('High-pass','hpf',20,1000,c.hpf,1,'Hz')}${control('Low shelf · 120 Hz','low',-12,12,c.low,.5,'dB')}${control('Mid · 1.1 kHz','mid',-12,12,c.mid,.5,'dB')}${control('High shelf · 6 kHz','high',-12,12,c.high,.5,'dB')}${control('Compression','comp',0,100,c.comp,1,'')}<label class="muted"><input type="checkbox" id="polarity" ${c.polarity?'checked':''}> Invert polarity</label></div>`;
$('#advancedToggle').onclick=()=>{$('#advancedControls').classList.toggle('open');$('#advancedToggle').textContent=$('#advancedControls').classList.contains('open')?'− EQ & dynamics':'＋ EQ & dynamics';};$('#polarity').onchange=e=>{checkpoint();c.polarity=e.target.checked;engine.update();save();};bindControls($('#pieceControls'));}
function selectLane(id){selected=id;renderInspector();$$('.kit-piece').forEach(e=>e.classList.toggle('selected',e.dataset.lane===id));$$('.channel-strip').forEach(e=>e.classList.toggle('selected',e.dataset.channel===LANES.find(l=>l.id===id).ch));}
function bindControls(root){root.querySelectorAll('[data-control]').forEach(input=>{input.onpointerdown=checkpoint;input.oninput=()=>{const target=input.dataset.scope==='master'?state.master:state.channels.find(c=>c.id===LANES.find(l=>l.id===selected).ch);target[input.dataset.control]=+input.value;root.querySelector(`[data-output="${input.dataset.scope}-${input.dataset.control}"]`).textContent=format(+input.value,input.dataset.unit);engine.update();save();};});}
function renderMixer(){$('#mixer').innerHTML=state.channels.map(c=>`<div class="channel-strip ${LANES.find(l=>l.id===selected).ch===c.id?'selected':''}" data-channel="${c.id}"><h3 tabindex="0">${c.name}</h3><div class="sm"><button data-mix="mute" class="${c.mute?'on':''}" aria-label="Mute ${c.name}">M</button><button data-mix="solo" class="${c.solo?'on':''}" aria-label="Solo ${c.name}">S</button></div><div class="pan-label">PAN</div><input class="pan" aria-label="${c.name} pan" data-mix="pan" type="range" min="-1" max="1" step=".01" value="${c.pan}"><input class="fader" aria-label="${c.name} level" data-mix="volume" type="range" min="0" max="1.5" step=".01" value="${c.volume}"><div class="strip-value">${c.volume===0?'−∞':(20*Math.log10(c.volume)).toFixed(1)} dB</div></div>`).join('');$$('.channel-strip').forEach(el=>{const c=state.channels.find(c=>c.id===el.dataset.channel);el.querySelector('h3').onclick=()=>selectLane(LANES.find(l=>l.ch===c.id).id);el.querySelector('h3').onkeydown=e=>{if(e.key==='Enter')el.querySelector('h3').click()};el.querySelectorAll('button').forEach(b=>b.onclick=()=>{checkpoint();c[b.dataset.mix]=!c[b.dataset.mix];b.classList.toggle('on',c[b.dataset.mix]);engine.update();save();});el.querySelectorAll('input').forEach(i=>{i.onpointerdown=checkpoint;i.oninput=()=>{c[i.dataset.mix]=+i.value;el.querySelector('.strip-value').textContent=c.volume===0?'−∞ dB':(20*Math.log10(c.volume)).toFixed(1)+' dB';engine.update();if(LANES.find(l=>l.id===selected).ch===c.id)renderInspector();save();};});});
$('#masterControls').innerHTML=control('Room return','room',0,1,state.master.room,.01,'%','master')+control('Parallel comp','parallel',0,1,state.master.parallel,.01,'%','master')+control('Bus glue','glue',0,100,state.master.glue,1,'','master')+control('Low shelf','low',-12,12,state.master.low,.5,'dB','master')+control('High shelf','high',-12,12,state.master.high,.5,'dB','master');bindControls($('#masterControls'));}
function libraryMatches(){return filterGrooves(GROOVES,{query:search,kind:grooveFilter,style:grooveStyle,meter:grooveMeter,feel:grooveFeel,tempo:grooveTempo,sort:grooveSort,favorites,savedOnly});}
function resetLibraryPage(){groovePage=0;renderLibrary();}
function renderLibrary(){
 $('#grooveCount').textContent=GROOVES.length.toLocaleString();
 const filters=[['All','All'],['Groove','Grooves'],['Fill','Fills'],['Intro','Intros'],['Ending','Endings']];
 $('#filters').innerHTML=filters.map(([value,label])=>`<button data-filter="${value}" class="${grooveFilter===value?'active':''}" aria-pressed="${grooveFilter===value}">${label}</button>`).join('')+`<button id="savedGrooves" class="${savedOnly?'active':''}" aria-pressed="${savedOnly}" aria-label="Show favourite grooves">★ ${favorites.size}</button>`;
 const list=libraryMatches(),pages=Math.max(1,Math.ceil(list.length/PAGE_SIZE));groovePage=Math.max(0,Math.min(groovePage,pages-1));
 $('#libraryResults').textContent=`${list.length.toLocaleString()} matches`;
 $('#groovePage').textContent=`${groovePage+1} / ${pages}`;
 $('#groovePrev').disabled=groovePage===0;$('#grooveNext').disabled=groovePage===pages-1;
 $('#grooveList').innerHTML=list.slice(groovePage*PAGE_SIZE,(groovePage+1)*PAGE_SIZE).map(({p,index})=>{
 const auditioning=playing&&libraryPreview?.id===p.id;
 return `<div class="groove ${previewName===p.name?'selected':''}" draggable="true" data-groove="${index}" title="${esc(p.name)}"><button class="audition" aria-label="${auditioning?'Stop':'Play'} ${esc(p.name)}">${auditioning?'■':'▶'}</button><div class="groove-info"><button class="groove-name" aria-label="Load ${esc(p.name)} into editor">${esc(p.name)}</button><small>${p.bars} bars · ${p.signature} · ${p.feel||'Straight'} · <b>${p.bpm} BPM</b></small><small class="groove-kind">${p.kind}${p.section&&p.kind==='Groove'?' · '+esc(p.section):''}</small></div><div class="groove-actions"><button class="groove-star ${favorites.has(p.id)?'is-saved':''}" aria-label="${favorites.has(p.id)?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${favorites.has(p.id)}">${favorites.has(p.id)?'★':'☆'}</button><button class="groove-add" aria-label="Add ${esc(p.name)} to song">＋</button></div></div>`;
 }).join('')||'<div class="empty">No grooves match these filters.<br>Try a broader search or reset filters.</div>';
 $$('[data-filter]').forEach(b=>b.onclick=()=>{grooveFilter=b.dataset.filter;resetLibraryPage();});
 $('#savedGrooves').onclick=()=>{savedOnly=!savedOnly;resetLibraryPage();};
}
function initializeLibrary(){
 const families=[...new Set(GROOVES.map(p=>p.family))].sort();
 $('#libraryStyle').innerHTML='<option value="All">All styles</option><optgroup label="Style groups">'+families.map(f=>`<option value="family:${esc(f)}">${esc(f)}</option>`).join('')+'</optgroup>'+families.map(f=>`<optgroup label="${esc(f)}">${[...new Set(GROOVES.filter(p=>p.family===f).map(p=>p.style))].sort().map(style=>`<option value="style:${esc(style)}">${esc(style)}</option>`).join('')}</optgroup>`).join('');
 $('#libraryMeter').innerHTML='<option value="All">Any meter</option>'+Object.keys(SIGNATURES).map(m=>`<option>${m}</option>`).join('');
 for(const [id,set]of [['libraryStyle',v=>grooveStyle=v],['libraryMeter',v=>grooveMeter=v],['libraryFeel',v=>grooveFeel=v],['libraryTempo',v=>grooveTempo=v],['librarySort',v=>grooveSort=v]])$('#'+id).onchange=e=>{set(e.target.value);resetLibraryPage();};
 $('#auditionTempo').onchange=()=>{if(libraryPreview)$('#libraryPreviewStatus').textContent=`Auditioning: ${libraryPreview.name} · ${playbackBpm()} BPM`;};
 $('#groovePrev').onclick=()=>{groovePage--;renderLibrary();$('#grooveList').scrollTop=0;};$('#grooveNext').onclick=()=>{groovePage++;renderLibrary();$('#grooveList').scrollTop=0;};
 $('#resetGrooveFilters').onclick=()=>{search='';grooveFilter='All';grooveStyle=grooveMeter=grooveFeel=grooveTempo='All';grooveSort='collection';savedOnly=false;$('#grooveSearch').value='';for(const id of ['libraryStyle','libraryMeter','libraryFeel','libraryTempo'])$('#'+id).value='All';$('#librarySort').value='collection';resetLibraryPage();};
 $('#grooveList').onclick=async e=>{const row=e.target.closest('[data-groove]');if(!row)return;const index=+row.dataset.groove,g=GROOVES[index];
 if(e.target.closest('.groove-star')){if(favorites.has(g.id))favorites.delete(g.id);else favorites.add(g.id);try{localStorage.setItem('iron-room-groove-favorites',JSON.stringify([...favorites]));}catch{}renderLibrary();return;}
 if(e.target.closest('.audition')){if(playing&&libraryPreview?.id===g.id){stop();return;}previewName=g.name;await play(g);renderLibrary();return;}
 if(e.target.closest('.groove-add')){checkpoint();const i=loadGroove(index);if(i===null)return;addClip(i);toast('Groove added to song');return;}
 if(e.target.closest('.groove-name')){checkpoint();const i=loadGroove(index);if(i===null)return;stop();state.active=i;selectedNote=null;renderEditor();setTab('editor');save();toast('Groove loaded into editor');}
 };
 $('#grooveList').ondragstart=e=>{const row=e.target.closest('[data-groove]');if(!row)return;dragData={groove:+row.dataset.groove};e.dataTransfer.setData('text/plain',JSON.stringify(dragData));};
 $('#downloadGrooves').onclick=async()=>{const matches=libraryMatches();if(!matches.length)return toast('No matching grooves to download.');const button=$('#downloadGrooves');button.disabled=true;button.textContent='Preparing MIDI pack…';try{const files=[];for(let i=0;i<matches.length;i++){const {p}=matches[i],name=p.name.replace(/[^a-z0-9]+/gi,'-').replace(/-$/,'');files.push([`${p.family.replace(/[^a-z0-9]+/gi,'-')}/${p.kind}/${name}.mid`,exportMidi(p.events,p.bpm,p.signature,p.bars*SIGNATURES[p.signature])]);if(i%150===0)await new Promise(r=>setTimeout(r,0));}files.push(['LICENSE.txt',new TextEncoder().encode(PATTERN_LICENSE)]);files.push(['README.txt',new TextEncoder().encode('Iron Room original groove library. MIT licensed. Acoustic drum-kit interpretations, not sampled performances. Each MIDI file retains suggested BPM, meter, velocities and triplet offsets. GM drum mapping; semi-open hi-hat = 46, fully open = 26. Import Iron Room projects separately to preserve custom mappings. No GGD MIDI content is included.\n')]);download('iron-room-grooves.midipack.zip',zip(files));toast(`Downloaded ${matches.length.toLocaleString()} MIDI patterns`);}catch(err){toast('MIDI pack export failed: '+err.message);}finally{button.disabled=false;button.textContent='↓ Download filtered MIDI pack';}};
}
function loadGroove(i){const g=GROOVES[i];previewName=g.name;let index=state.patterns.findIndex(p=>p.libraryId===g.id||p.name===g.name);if(index<0){if(state.patterns.length>=200){toast('This project has 200 patterns. Start a new project before adding more.');return null;}state.patterns.push({...structuredClone(g),id:crypto.randomUUID(),libraryId:g.id});index=state.patterns.length-1;}return index;}
function addClip(index=state.active){if(index===null||!state.patterns[index])return;if(state.song.length>=64)return toast('A song can contain up to 64 clips.');state.song.push({pattern:index,repeats:1});renderSong();save();}
