function totalSteps(mode=state.mode){return mode==='pattern'?pattern().bars*SIGNATURES[pattern().signature]:state.song.reduce((n,c)=>n+state.patterns[c.pattern].bars*SIGNATURES[state.patterns[c.pattern].signature]*c.repeats,0);}
