$('#connectMidi').onclick=async()=>{if(!navigator.requestMIDIAccess)return toast('Web MIDI is unavailable in this browser. Try Chrome or Edge on desktop.');try{await ensureAudio();midiAccess=await navigator.requestMIDIAccess({sysex:false});const bind=()=>{const inputs=[...midiAccess.inputs.values()];$('#midiStatus').textContent=inputs.length?inputs.map(x=>x.name).join(', '):'MIDI enabled · connect an input device';for(const input of inputs)input.onmidimessage=message=>{const [s,n,v]=message.data;if((s&240)===176&&n===4){hatCC=v;return;}if((s&240)===160&&v>0){const mapped=LANES.find(l=>l.id===state.midiMap[n]);if(mapped&&['crash1','crash2','ride','china','splash'].includes(mapped.ch))choke(mapped.ch);return;}if((s&240)===208&&n>0){choke();return;}if((s&240)===128||((s&240)===144&&v===0))return;if((s&240)!==144||!v)return;if(learn){checkpoint();state.midiMap[n]=selected;learn=false;$('#learnMidi').checked=false;renderMidi();save();toast(`MIDI ${n} → ${LANES.find(l=>l.id===selected).name}`);return;}let lane=state.midiMap[n];if(['closed','semi','open'].includes(lane)){lane=hatCC>95?'closed':hatCC>30?'semi':'open';if(lane==='semi')state.variants.semi=Math.max(0,Math.min(6,Math.round((95-hatCC)/65*6)));}if(lane)liveHit(lane,v);};};bind();midiAccess.onstatechange=bind;}catch(err){toast('Could not connect MIDI: '+err.message);}};$('#learnMidi').onchange=e=>learn=e.target.checked;$('#recordMidi').onchange=e=>{record=e.target.checked;toast(record?'Live recording armed · press Play to record':'Live recording off');};
