$('#exportBtn').onclick=exportDialog;
async function renderAudio(stems){const mode=$('#exportMode').value,feel=$('#exportFeel').checked,events=compiled(mode);if(!events.length)return toast('Add some notes before exporting.');const duration=totalSteps(mode)*60/state.bpm/4+4;if(duration>240){$('#renderStatus').textContent='This export exceeds 4 minutes. Shorten the arrangement or render individual sections.';return;}const buttons=$$('#modal button');buttons.forEach(b=>b.disabled=true);stop();try{await ensureAudio();$('#renderStatus').textContent='Loading any missing samples…';await engine.loadCurrent();const originalRR={...engine.rr};let seed=137;const rand=()=>{seed=(seed*16807)%2147483647;return seed/2147483647};const timeline=events.filter(e=>!feel||rand()<=(e.prob??1)).map(e=>({...e,time:Math.max(0,.05+(e.step+(feel&&(e.step%2)&&(!atStep(e.step,mode)?.p.feel||atStep(e.step,mode)?.p.feel==='Straight')?state.swing/100:0)+(e.offset||0))*60/state.bpm/4+(feel?(rand()*2-1)*state.humanize/1000:0)),vel:Math.max(1,Math.min(127,e.velocity+(feel?(rand()*2-1)*state.velocityHumanize:0)))}));const channels=stems?state.channels.filter(c=>timeline.some(e=>LANES.find(l=>l.id===e.lane).ch===c.id)).map(c=>c.id):[null];const files=[];
for(let i=0;i<channels.length;i++){engine.rr={...originalRR};const ch=channels[i],ctx=new OfflineAudioContext(2,Math.ceil((duration+.05)*44100),44100),g=engine.buildGraph(ctx,ch);if(stems){g.master.gain.value=1;g.low.gain.value=0;g.high.gain.value=0;g.glue.ratio.value=1;g.glue.threshold.value=0;g.parallelGain.gain.value=0;g.roomGain.gain.value=0;g.limiter.ratio.value=1;g.limiter.threshold.value=0;}
const selectedEvents=timeline.filter(e=>!ch||LANES.find(l=>l.id===e.lane).ch===ch);for(const e of selectedEvents){await engine.hit(e.lane,e.vel,e.time,g,false);}$('#renderStatus').textContent=`Rendering ${ch?state.channels.find(c=>c.id===ch).name:'stereo master'} (${i+1}/${channels.length})…`;await new Promise(r=>setTimeout(r,20));const buffer=await ctx.startRendering();files.push([`iron-room-${ch||'mix'}.wav`,wav(buffer)]);$('#renderProgress').style.width=((i+1)/channels.length*100)+'%';}
engine.rr=originalRR;if(stems){files.push(['README.txt',new TextEncoder().encode('Iron Room — aligned stereo channel stems, 44.1 kHz 16-bit.\nPost channel EQ/compression/pan, pre-master, room excluded. Muted/unsoloed channels are silent as in your mix.\nSamples: Alexander Holm, Salamander Drumkit, CC BY-SA 3.0. https://github.com/studiorack/salamander-drumkit\n')]);download('iron-room-stems.zip',zip(files));}else download(files[0][0],files[0][1],'audio/wav');$('#renderStatus').textContent='Done. Your download is ready.';toast(stems?'Channel stems exported':'Stereo WAV exported');}catch(err){$('#renderStatus').textContent='Export failed: '+err.message;}finally{buttons.forEach(b=>b.disabled=false);$('#playBtn').textContent='▶';}}
$('#helpBtn').onclick=()=>modal(`<div class="eyebrow">WELCOME TO IRON ROOM</div><h2>A good room. A great groove.</h2><p>Play an acoustic kit with real recorded samples. Press <kbd>Space</kbd> to play or pause. The first play loads the kit; allow a moment on slower connections.</p><h3>Make a track</h3><ol><li>Audition a groove in the library. Use ＋ to add it to the song, or click its name to load it into the editor.</li><li>Open the Groove editor: draw hits, drag to move them, Shift-click or box-select groups, and Alt-drag to copy. Drag velocity bars below the grid. Select a straight or triplet snap, or switch snapping off.</li><li>Use Ghost, Flam, Roll ×4 and Quantize on selected notes. Set a loop region for Groove playback; the transport loop button must be enabled. Song playback and exports use complete patterns.</li><li>Save edited patterns in My Grooves for reuse. Ctrl/⌘ C/V/D copies, pastes at the ruler marker, and duplicates hits. Arrow keys nudge; Shift-arrows move by fine increments.</li><li>Arrange clips, set repeats, and switch the transport from Groove to Song.</li><li>Balance the mixer and choose a mix preset. Open EQ & dynamics in the kit-piece panel for channel processing.</li><li>Export stereo WAV, aligned channel stems, MIDI, or a portable project. Projects also autosave in this browser.</li></ol><p><a href="./iron-room-source.zip" download>Download the full source and samples (.zip)</a></p><h3>Performance keys</h3><p>Kick B · Snare F · Cross-stick D · Wires-off G · Closed hat H · Half-open J · Open K · Pedal L · Rack R · Floor T · Crash Q/W · Ride E · Bell Y · China U · Splash I · Cowbell O · Choke X. Undo Ctrl/⌘ Z, redo Shift Ctrl/⌘ Z.</p><h3>Samples & credits</h3><p><a href="https://github.com/studiorack/salamander-drumkit" target="_blank" rel="noopener">Salamander Drumkit</a> recorded by Alexander Holm, distributed under <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener">CC BY-SA 3.0</a>. The bundled 201-sample web edition trims leading silence and encodes high-quality MP3 for efficient delivery. Adapted samples retain that licence. <a href="./SAMPLE-LICENSE">Full sample licence</a>. Grooves and application code are original. Recorded music may be licensed independently, per the original library's licence clarification.</p><h3>What this version covers</h3><p>17 articulations, 2 kick recordings, 2 snares plus wires-off/cross-stick, 2 toms, 3 crashes, 2 rides with bells, 2 chinas, splash, cowbell, 7 semi-open hat positions, up to 4 velocity layers and 3 alternate hits per layer; ${GROOVES.length.toLocaleString()} original patterns across 50 new style collections plus the original starter grooves; 11 mixer channels; sample import; MIDI mapping/learn and CC4; WAV, stems and MIDI export.</p><h3>How it differs from GetGood Drums</h3><p>Iron Room is an independent web instrument. It does not include GGD recordings, its proprietary engine, its full catalogue of kit pieces/grooves, authentic separate close/overhead/room microphone stems or adjustable recorded bleed. These samples are stereo overhead recordings; room is generated with convolution. There is no VST/AU/AAX or DAW multi-output integration, host synchronization, disk-streaming sampler or tempo-map automation. Web MIDI requires a compatible browser. Long audio exports are limited to four minutes to keep browser memory manageable.</p>`);
// Local sample storage. Portable project exports embed these same bytes.
function customDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('iron-room-samples',1);req.onupgradeneeded=()=>req.result.createObjectStore('samples',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function getCustomSamples(){try{const db=await customDB();return await new Promise((resolve,reject)=>{const req=db.transaction('samples').objectStore('samples').getAll();req.onsuccess=()=>{db.close();resolve(req.result)};req.onerror=()=>reject(req.error)});}catch{return [];}}
async function storeCustomSamples(samples){const db=await customDB();await new Promise((resolve,reject)=>{const tx=db.transaction('samples','readwrite'),store=tx.objectStore('samples');store.clear();for(const sample of samples)store.put(sample);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();}
const customManifest={};
async function installCustomSamples(samples){for(const l of LANES){l.variants=l.variants.filter(v=>!v.custom);const own=samples.filter(s=>s.lane===l.id);if(!own.length)continue;const buckets=new Map();for(const s of own){const velocity=+s.velocity||127;if(!buckets.has(velocity))buckets.set(velocity,[]);buckets.get(velocity).push(URL.createObjectURL(new Blob([s.data])));}const groups=[];for(const [vel,urls]of [...buckets.entries()].sort((a,b)=>a[0]-b[0])){const key=`custom_${l.id}_${vel}`;customManifest[key]=urls;groups.push([vel,key]);}groups.at(-1)[0]=127;l.variants.push({label:'Your samples · '+own.length+' recordings',custom:true,groups});}if(engine.manifest)Object.assign(engine.manifest,customManifest);engine.customManifest=customManifest;}
$('#customSample').onclick=()=>{modal(`<div class="eyebrow">YOUR OWN RECORDINGS</div><h2>Bring a new sound.</h2><p>Load samples into <b>${esc(LANES.find(l=>l.id===selected).name)}</b>. Single files work immediately. For velocity layers, name files <b>snare_v40_rr1.wav</b>, <b>snare_v90_rr1.wav</b>, <b>snare_v127_rr1.wav</b>. The v number is the layer's upper velocity; files with the same number cycle as alternate hits.</p><p>Samples stay in this browser and are embedded when you download a project. Up to 80 custom files and 64 MB in total.</p><button class="primary" id="chooseSamples">Choose samples</button>`);$('#chooseSamples').onclick=()=>{$('#modal').close();$('#sampleFiles').click();};};
$('#sampleFiles').onchange=async e=>{try{const files=[...e.target.files];if(!files.length)return;await ensureAudio();const previous=(await getCustomSamples()).filter(s=>s.lane!==selected);if(previous.length+files.length>80||previous.reduce((n,s)=>n+s.data.byteLength,0)+files.reduce((n,f)=>n+f.size,0)>64e6)throw Error('Custom sample limit is 80 files / 64 MB.');const next=[];for(const f of files){const data=await f.arrayBuffer();await engine.ctx.decodeAudioData(data.slice(0));next.push({id:crypto.randomUUID(),lane:selected,name:f.name,velocity:Math.min(127,Math.max(1,+(f.name.match(/[_-]v(\d+)/i)?.[1]||127))),data});}await storeCustomSamples([...previous,...next]);await installCustomSamples([...previous,...next]);checkpoint();state.variants[selected]=LANES.find(l=>l.id===selected).variants.length-1;renderInspector();save();toast(`${next.length} custom recordings loaded`);}catch(err){toast('Could not load samples: '+err.message);}e.target.value='';};
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||$('#modal').open)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if(e.repeat)return;if(e.code==='Space'){e.preventDefault();playing?stop():play();return;}if(e.key.toLowerCase()==='x'){choke();return;}const l=LANES.find(l=>l.key===e.key.toLowerCase());if(l){e.preventDefault();selectLane(l.id);liveHit(l.id,e.shiftKey?45:105);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing){stop();toast('Playback paused while the tab was inactive.');}});
// Restore custom instruments before validating their saved variant indices.
await installCustomSamples(await getCustomSamples());try{const saved=JSON.parse(localStorage.getItem('iron-room-v1'));if(saved){state=validateProject(saved);engine.state=state;}}catch{}
initializeLibrary();renderAll();tick();
